  `GOALS_AWAY` varchar(6) COLLATE utf8_unicode_ci DEFAULT NULL,
  `POINTS_HOME` varchar(6) COLLATE utf8_unicode_ci DEFAULT NULL,
  `POINTS_AWAY` varchar(6) COLLATE utf8_unicode_ci DEFAULT NULL,
