  `UPDATE_DTM` timestamp NOT NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;




CREATE ALGORITHM=UNDEFINED DEFINER=`id1895186_brodahut`@`%` SQL SECURITY DEFINER VIEW `MANAGER_MONTH_V` AS select year(`GI`.`INSERT_DTM`) AS `year`,month(`GI`.`INSERT_DTM`) AS `monthnum`,date_format(`GI`.`INSERT_DTM`,'%M') AS `month`,`GI`.`PLAYER_NAME` AS `PLAYER_NAME`,(select `GW`.`PROPERTY` from `GAMEWEEK_INFO` `GW` where `GW`.`PLAYER_NAME` = `GI`.`PLAYER_NAME` and `GW`.`SEASON` = 1 and `GW`.`GAMEWEEK` = max(`GI`.`GAMEWEEK`)) - (select `GW`.`PROPERTY` from `GAMEWEEK_INFO` `GW` where `GW`.`PLAYER_NAME` = `GI`.`PLAYER_NAME` and `GW`.`SEASON` = 1 and `GW`.`GAMEWEEK` = min(`GI`.`GAMEWEEK`)) AS `economical_growth`,sum(`GI`.`TOTAL`) AS `payments`,sum(`GI`.`TEAM_SALARY`) AS `multas`,sum(`GI`.`POSITION_PRIZE`) AS `premis`,sum(`GI`.`GAMEWEEK_POINTS`) AS `POINTS`,sum(`GI`.`CAPTAIN_POINTS`) AS `POINTS_CAPTAIN`,sum(`GI`.`BEST_LINEUP`) AS `best_lineup`,`GI`.`SEASON` AS `season` from `GAMEWEEK_INFO` `GI` where `GI`.`SEASON` = 1 group by year(`GI`.`INSERT_DTM`),month(`GI`.`INSERT_DTM`),`GI`.`SEASON`,`GI`.`PLAYER_NAME`,date_format(`GI`.`INSERT_DTM`,'%M') order by 1,2,9 desc;




CREATE ALGORITHM=UNDEFINED DEFINER=`id1895186_brodahut`@`%` SQL SECURITY DEFINER VIEW `MANAGER_SEASON_V` AS select NULL AS `year`,NULL AS `monthnum`,'Season' AS `month`,`GI`.`PLAYER_NAME` AS `PLAYER_NAME`,(select `GW`.`PROPERTY` from `GAMEWEEK_INFO` `GW` where `GW`.`PLAYER_NAME` = `GI`.`PLAYER_NAME` and `GW`.`SEASON` = 1 and `GW`.`GAMEWEEK` = max(`GI`.`GAMEWEEK`)) - (select `GW`.`PROPERTY` from `GAMEWEEK_INFO` `GW` where `GW`.`PLAYER_NAME` = `GI`.`PLAYER_NAME` and `GW`.`SEASON` = 1 and `GW`.`GAMEWEEK` = min(`GI`.`GAMEWEEK`)) AS `economical_growth`,sum(`GI`.`TOTAL`) AS `payments`,sum(`GI`.`TEAM_SALARY`) AS `multas`,sum(`GI`.`POSITION_PRIZE`) AS `premis`,sum(`GI`.`GAMEWEEK_POINTS`) AS `POINTS`,sum(`GI`.`CAPTAIN_POINTS`) AS `POINTS_CAPTAIN`,sum(`GI`.`BEST_LINEUP`) AS `best_lineup`,`GI`.`SEASON` AS `season` from `GAMEWEEK_INFO` `GI` group by `GI`.`SEASON`,`GI`.`PLAYER_NAME` order by 4 desc;




